import React, { createContext, useState, useEffect, useContext, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../services/apiService';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [socket, setSocket] = useState(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const navigate = useNavigate();

  // Initialize WebSocket connection
  const initWebSocket = useCallback((token) => {
    if (!token) return null;

    // Close existing socket if it exists
    if (socket) {
    }

    if (!token) {
      console.log('No token available for WebSocket connection');
      return null;
    }

    console.log('Initializing new WebSocket connection with token:', token.substring(0, 10) + '...');
    
    try {
      const newSocket = io(process.env.REACT_APP_WS_URL || 'http://localhost:5000', {
        path: '/socket.io',
        transports: ['websocket', 'polling'],
        reconnection: true,
        reconnectionAttempts: 10,
        reconnectionDelay: 1000,
        reconnectionDelayMax: 10000,
        timeout: 20000,
        auth: { token },
        query: { token },
        withCredentials: true,
        autoConnect: true,
        forceNew: true,
        secure: process.env.NODE_ENV === 'production',
        rejectUnauthorized: false
      });

      // Set up event handlers
      newSocket.on('connect', () => {
        console.log('WebSocket connected with ID:', newSocket.id);
        setSocketConnected(true);
        
        // No need to manually authenticate - handled by middleware
        console.log('WebSocket connection established, waiting for authentication...');
      });

      newSocket.on('authenticated', (data) => {
        console.log('WebSocket authenticated successfully', data);
        setSocketAuthenticated(true);
        
        // Join user's personal room
        if (user?._id) {
          newSocket.emit('join', { userId: user._id });
        }
      });

      newSocket.on('authentication_error', (error) => {
        console.error('WebSocket authentication failed:', error);
        setSocketAuthenticated(false);
        // Don't disconnect here - let the server handle it
      });

      newSocket.on('connect_error', (error) => {
        console.error('WebSocket connection error:', error.message);
        setSocketConnected(false);
        setSocketAuthenticated(false);
        
        // For auth errors, clear the token and redirect to login
        if (error.message.includes('401') || error.message.includes('403')) {
          console.log('Authentication error, logging out...');
          logout();
        }
      });

      newSocket.on('disconnect', (reason) => {
        console.log('WebSocket disconnected. Reason:', reason);
        setSocketConnected(false);
        setSocketAuthenticated(false);
        
        // Only attempt to reconnect if user is still logged in
        if (user) {
          console.log('Attempting to reconnect WebSocket in 3 seconds...');
          const reconnectTimer = setTimeout(() => {
            if (user) {  // Check again in case user logged out during delay
              initWebSocket(token);
            }
          }, 3000);
          
          // Clean up timer if component unmounts
          return () => clearTimeout(reconnectTimer);
        }
      });

      newSocket.on('error', (error) => {
        console.error('WebSocket error:', error);
      });

      // Store the socket reference
      socketRef.current = newSocket;
      return newSocket;
      
    } catch (error) {
      console.error('Error initializing WebSocket:', error);
      return null;
    }
  }, [socket, user]);

  // Clean up WebSocket connection
  const cleanupWebSocket = useCallback(() => {
    if (socket) {
      socket.close(1000, 'User logged out');
      setSocket(null);
    }
  }, [socket]);
  // Check authentication status on mount
  useEffect(() => {
    let ws = null;
    let isMounted = true;
    
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) {
          // No token, set as not authenticated
          setUser(null);
          return;
        }
        
        // If we have a token, verify it
        try {
          // First try the /me endpoint (preferred)
          let response;
          try {
            response = await api.get('/auth/me', {
              // Don't retry this request to avoid infinite loading
              retry: 0
            });
          } catch (meError) {
            // Fall back to /profile if /me fails
            console.log('Falling back to /profile endpoint');
            response = await api.get('/auth/profile', {
              retry: 0
            });
          }
          
          if (isMounted) {
            // Handle both response formats
            const userData = response.data.user || response.data;
            setUser(userData);
            // Initialize WebSocket after successful auth
            ws = initWebSocket(token);
          }
        } catch (error) {
          console.error('Token validation failed:', error);
          if (error.response?.status !== 401) {
            // Only show error if it's not a 401 (unauthorized)
            toast.error('Failed to verify session. Please log in again.');
          }
          localStorage.removeItem('token');
          setUser(null);
        }
      } catch (error) {
        console.error('Auth check failed:', error);
        if (isMounted) {
          setUser(null);
          // Don't show error toast here to avoid spamming the user
        }
      } finally {
        if (isMounted) {
          setLoading(false);
          setIsInitialized(true);
        }
      }
    };

    checkAuth();
    
    return () => {
      isMounted = false;
      if (ws) {
        cleanupWebSocket(ws);
      }
    };
  }, [initWebSocket, cleanupWebSocket]);

  // Login function with enhanced error handling and rate limiting support
  const login = async (email, password) => {
    setLoading(true);
    setError(null);
  
    try {
      const response = await api.post('/auth/login', { email, password }, { 
        retry: 3,
        retryCount: 0
      });
      
      const { token, user } = response.data;
      
      if (!token || !user) {
        throw new Error('Invalid response from server: Missing token or user data');
      }
      
      // Store token in localStorage and set default Authorization header
      localStorage.setItem('token', token);
      api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
      
      // Set user state
      setUser(user);
      
      // Initialize WebSocket with a small delay to ensure state is updated
      setTimeout(() => {
        initWebSocket(token);
      }, 100);
      
      // Show success message
      toast.success('Successfully logged in!');
      
      // Navigate after state is updated
      navigate('/dashboard', { replace: true });
      
      return { success: true };
    } catch (error) {
      let errorMessage = 'Login failed. Please check your credentials and try again.';
      
      if (error.response?.status === 429) {
        errorMessage = 'Too many login attempts. Please wait a moment and try again.';
      } else if (error.response?.data?.message) {
        errorMessage = error.response.data.message;
      } else if (error.message) {
        errorMessage = error.message;
      }
      
      console.error('Login error:', error);
      setError(errorMessage);
      toast.error(errorMessage);
      
      // Clear any invalid tokens
      localStorage.removeItem('token');
      delete api.defaults.headers.common['Authorization'];
      
      return { success: false, error: errorMessage };
    } finally {
      setLoading(false);
    }
  };

  // Register function with validation
  const register = async (userData) => {
    setLoading(true);
    setError(null);
    
    try {
      const response = await api.post('/auth/register', userData);
      const { token, user } = response.data;
      
      localStorage.setItem('token', token);
      setUser(user);
      
      // Initialize WebSocket after successful registration
      initWebSocket(token);
      
      toast.success('Registration successful! Welcome to PulsePoint!');
      navigate('/dashboard'); // Navigate after successful registration
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Registration failed. Please try again.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    } finally {
      setLoading(false);
    }
  };

  // Logout function with cleanup
  const logout = useCallback(() => {
    localStorage.removeItem('token');
    setUser(null);
    cleanupWebSocket(socket);
    setSocket(null);
    toast.info('You have been logged out.');
    navigate('/login');
  }, [navigate, socket, cleanupWebSocket]);

  // Update user profile
  const updateProfile = async (userData) => {
    try {
      const response = await api.put('/auth/me', userData);
      setUser(prev => ({
        ...prev,
        ...response.data.user
      }));
      toast.success('Profile updated successfully!');
      return { success: true };
    } catch (error) {
      const errorMessage = error.response?.data?.message || 'Failed to update profile.';
      setError(errorMessage);
      toast.error(errorMessage);
      return { 
        success: false, 
        message: errorMessage,
        errors: error.response?.data?.errors
      };
    }
  };

  // Refresh token function
  const refreshToken = async () => {
    try {
      const response = await api.post('/auth/refresh-token');
      const { token, user: userData } = response.data;
      
      localStorage.setItem('token', token);
      setUser(userData);
      
      return { success: true, token };
    } catch (error) {
      console.error('Failed to refresh token:', error);
      logout();
      return { success: false };
    }
  };

  // Context value
  const value = {
    user,
    loading,
    error,
    socket,
    isInitialized,
    isAuthenticated: !!user,
    login,
    register,
    logout,
    updateProfile,
    refreshToken,
    clearError: () => setError(null)
  };

  return (
    <AuthContext.Provider value={value}>
      {isInitialized ? children : null}
    </AuthContext.Provider>
  );
};

// Custom hook to use auth context
const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

export { AuthContext, useAuth };
export default AuthContext;
